begin;
create schema review_test;
create table review_test.results(name text,passed boolean);
grant usage on schema review_test to anon,authenticated;
create function review_test.assert(name text,ok boolean) returns void language plpgsql security definer as $$ begin
 if ok is distinct from true then raise exception 'ASSERTION FAILED: %',name;end if;
 insert into review_test.results values(name,true);end $$;
create function review_test.denied(name text,command text,expected text) returns void language plpgsql security invoker as $$ begin
 begin execute command;exception when others then
 if sqlerrm=expected then perform review_test.assert(name,true);return;end if;raise;end;
 raise exception 'ASSERTION FAILED: % (allowed)',name;end $$;
insert into auth.users(id,email_confirmed_at) values('f0000000-0000-4000-8000-000000000001',now()),('f0000000-0000-4000-8000-000000000002',now()),('f0000000-0000-4000-8000-000000000003',now());
insert into private.admin_owners(user_id) values('f0000000-0000-4000-8000-000000000001');
update public.profiles set display_name='Review Owl' where user_id='f0000000-0000-4000-8000-000000000002';
insert into public.movies(id,tmdb_id,title,original_title) values('f1000000-0000-4000-8000-000000000001',77777,'Review fixture','Review fixture');
insert into public.contributions(id,user_id,movie_id,revision,watched) values('f2000000-0000-4000-8000-000000000001','f0000000-0000-4000-8000-000000000002','f1000000-0000-4000-8000-000000000001',1,true);
insert into public.category_ratings(contribution_id,category_slug,severity) values('f2000000-0000-4000-8000-000000000001','nudity',2),('f2000000-0000-4000-8000-000000000001','horror',5);
select review_test.assert('flags are private and unavailable through raw API tables',not has_table_privilege('authenticated','private.admin_review_flags','SELECT') and not has_function_privilege('anon','public.set_admin_review_flag(uuid,bigint,text,text,text)','EXECUTE'));
set local role authenticated;
select set_config('request.jwt.claim.sub','f0000000-0000-4000-8000-000000000003',true);
select review_test.denied('non-owner cannot read review details',$q$select public.get_admin_review('f2000000-0000-4000-8000-000000000001')$q$,'FORBIDDEN');
select review_test.denied('non-owner cannot flag a review',$q$select public.set_admin_review_flag('f2000000-0000-4000-8000-000000000001',1,'flag','spam',null)$q$,'FORBIDDEN');
select review_test.denied('non-owner cannot read flagged queue',$q$select public.get_admin_flagged_reviews(5,0)$q$,'FORBIDDEN');
select set_config('request.jwt.claim.sub','f0000000-0000-4000-8000-000000000001',true);
select review_test.assert('detail contains every category rating and chosen nickname',jsonb_array_length(public.get_admin_review('f2000000-0000-4000-8000-000000000001')->'categories')=2 and public.get_admin_review('f2000000-0000-4000-8000-000000000001')->>'nickname'='Review Owl');
select review_test.assert('detail excludes auth identity and provider data',public.get_admin_review('f2000000-0000-4000-8000-000000000001')::text not like '%f0000000%' and public.get_admin_review('f2000000-0000-4000-8000-000000000001')::text not like '%email%');
select review_test.denied('different perspective is not a flag reason',$q$select public.set_admin_review_flag('f2000000-0000-4000-8000-000000000001',1,'flag','different_opinion',null)$q$,'INVALID_REQUEST');
select review_test.assert('flag mutation immediately returns the new flag',public.set_admin_review_flag('f2000000-0000-4000-8000-000000000001',1,'flag','spam','Repeated promotion')->'flag'->>'status'='open');
select public.set_admin_review_flag('f2000000-0000-4000-8000-000000000001',1,'flag','spam','Repeated promotion');
select review_test.assert('repeated flagging has one queue item',(public.get_admin_flagged_reviews(5,0)->>'total')::int=1 and jsonb_array_length(public.get_admin_flagged_reviews(5,0)->'reviews')=1);
select review_test.assert('flag records reason and inspected revision',public.get_admin_review('f2000000-0000-4000-8000-000000000001')->'flag'->>'reason'='spam' and (public.get_admin_review('f2000000-0000-4000-8000-000000000001')->'flag'->>'reviewRevision')::bigint=1);
select review_test.denied('stale inspected review cannot be flagged',$q$select public.set_admin_review_flag('f2000000-0000-4000-8000-000000000001',2,'flag','spam',null)$q$,'REVISION_CONFLICT');
select review_test.denied('invalid pagination is refused',$q$select public.get_admin_flagged_reviews(26,0)$q$,'INVALID_REQUEST');
reset role;
select review_test.assert('flag does not alter rating values or contribution visibility',(select sum(severity)=7 from public.category_ratings where contribution_id='f2000000-0000-4000-8000-000000000001') and (select visibility='active' and revision=1 from public.contributions where id='f2000000-0000-4000-8000-000000000001'));
update public.contributions set revision=2 where id='f2000000-0000-4000-8000-000000000001';
set local role authenticated;
select review_test.assert('queue marks reviews edited since flagging',(public.get_admin_flagged_reviews(5,0)->'reviews'->0->>'reviewChanged')::boolean);
select review_test.assert('resolve immediately returns the resolved state',public.set_admin_review_flag('f2000000-0000-4000-8000-000000000001',2,'resolve',null,null)->'flag'->>'status'='resolved');
select review_test.assert('resolved flags leave the open queue',(public.get_admin_flagged_reviews(5,0)->>'total')::int=0 and public.get_admin_review('f2000000-0000-4000-8000-000000000001')->'flag'->>'status'='resolved');
reset role;
select review_test.assert('resolution keeps restricted moderation record',(select count(*)=1 and bool_and(status='resolved') from private.admin_review_flags));
update private.user_access set status='suspended' where user_id='f0000000-0000-4000-8000-000000000001';
set local role authenticated;
select review_test.denied('suspended owner cannot moderate',$q$select public.set_admin_review_flag('f2000000-0000-4000-8000-000000000001',2,'flag','spam',null)$q$,'ACCOUNT_SUSPENDED');
reset role;
update private.user_access set status='active' where user_id='f0000000-0000-4000-8000-000000000001';
delete from private.admin_owners where user_id='f0000000-0000-4000-8000-000000000001';
set local role authenticated;
select review_test.denied('revoked owner immediately loses access',$q$select public.get_admin_flagged_reviews(5,0)$q$,'FORBIDDEN');
reset role;
select name,passed from review_test.results;
rollback;
